namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context");

        if (TryValidateContext(principal, resource, request, out var decision))
            return decision;

        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        if (TryApplySecurityPolicies(resource, request, administrator, out decision))
            return decision;

        if (TryDenyUnauthorizedAction(request.Action, administrator, operatorRole, auditor, owner, delegated, out decision))
            return decision;

        return Allow(resource, request, delegated);
    }

    private static bool TryValidateContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Denied("invalid-identity", out decision);
        if (principal.Suspended)
            return Denied("principal-suspended", out decision);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Denied("tenant-mismatch", out decision);
        if (resource.Locked && request.Action != "read")
            return Denied("resource-locked", out decision);
        if (request.MinuteOfDay is < 0 or > 1439)
            return Denied("invalid-time", out decision);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Denied("challenge-required", out decision);

        decision = default!;
        return false;
    }

    private static bool TryApplySecurityPolicies(
        Resource resource,
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (request.BreakGlass)
        {
            decision = administrator && request.StrongAuthentication
                ? new AccessDecision(true, "break-glass", true)
                : Deny("invalid-break-glass");
            return true;
        }

        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Denied("strong-authentication-required", out decision);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Denied("trusted-network-required", out decision);

        decision = default!;
        return false;
    }

    private static bool TryDenyUnauthorizedAction(
        string action,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated,
        out AccessDecision decision)
    {
        switch (action)
        {
            case "delete":
                return TryDenyDelete(administrator, out decision);
            case "write":
                return TryDenyWrite(administrator, operatorRole, owner, delegated, out decision);
            case "read":
                return TryDenyRead(administrator, operatorRole, auditor, owner, delegated, out decision);
            default:
                return Denied("unknown-action", out decision);
        }
    }

    private static bool TryDenyDelete(bool administrator, out AccessDecision decision)
    {
        if (!administrator)
            return Denied("administrator-required", out decision);

        decision = default!;
        return false;
    }

    private static bool TryDenyWrite(
        bool administrator,
        bool operatorRole,
        bool owner,
        bool delegated,
        out AccessDecision decision)
    {
        if (!(administrator || operatorRole || owner || delegated))
            return Denied("write-not-authorised", out decision);

        decision = default!;
        return false;
    }

    private static bool TryDenyRead(
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated,
        out AccessDecision decision)
    {
        if (!(administrator || operatorRole || auditor || owner || delegated))
        {
            decision = new AccessDecision(false, "read-not-authorised", false);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision Allow(Resource resource, AccessRequest request, bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        var reason = delegated ? "delegated" : "role-or-ownership";
        var requiresAudit = outsideBusinessHours || resource.Classification == "restricted";
        return new AccessDecision(true, reason, requiresAudit);
    }

    private static bool Denied(string reason, out AccessDecision decision)
    {
        decision = Deny(reason);
        return true;
    }

    private static AccessDecision Deny(string reason) => new(false, reason, true);
}
